#!/usr/bin/env pwsh
#Requires -Version 7.0
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill. PowerShell 7 port of template.sh: same helper
# names, same behaviour, so a stage translates call for call.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

$_TTY = -not [Console]::IsOutputRedirected
if ($_TTY) {
  $BOLD = "`e[1m"; $DIM = "`e[2m"; $RESET = "`e[0m"
  $BLUE = "`e[34m"; $GREEN = "`e[32m"; $YELLOW = "`e[33m"
} else {
  $BOLD = ''; $DIM = ''; $RESET = ''; $BLUE = ''; $GREEN = ''; $YELLOW = ''
}

# Author sets this at the top of the stages section, as $script:TOTAL_STAGES.
$TOTAL_STAGES = 0

$_STAGE_INDEX = 0
$ENV_FILE = if ($env:ENV_FILE) { $env:ENV_FILE } else { '.env' }
$WRITTEN_ENV = [Collections.Generic.List[string]]::new()    # KEYs written to ENV_FILE this run
$WRITTEN_SECRET = [Collections.Generic.List[string]]::new() # secret NAMEs set this run
$SKIPPED = [Collections.Generic.List[string]]::new()        # things we couldn't do (e.g. gh missing)

# .NET file APIs resolve against the process cwd, not the PowerShell location.
function _env_path { $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($ENV_FILE) }

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
function _clear { if ($_TTY) { [Console]::Write("`e[2J`e[3J`e[H") } }

# banner "Title" shows the opening frame: what this wizard does.
function banner([string]$Title) {
  _clear
  Write-Host "`n$BOLD$BLUE  $Title$RESET"
  Write-Host "$DIM  $TOTAL_STAGES stages$RESET`n"
  Write-Host "$DIM  You drive the browser; this wizard tells you exactly what to do and"
  Write-Host '  captures the values you copy back. Stop any time with Ctrl-C and re-run'
  Write-Host "  later, since it remembers values already saved.$RESET"
  pause 'Ready to start?'
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
function stage([string]$Name) {
  _clear
  $script:_STAGE_INDEX++
  Write-Host "`n$BOLD$BLUE▸ Stage $($script:_STAGE_INDEX)/$TOTAL_STAGES · $Name$RESET"
}

# say "..." prints a plain instruction line.
function say([string]$Text) { Write-Host "  $Text" }
# step "..." is a numbered-feeling action the human takes in the browser.
function step([string]$Text) { Write-Host "  $BLUE•$RESET $Text" }
function note([string]$Text) { Write-Host "  $DIM$Text$RESET" }
function warn([string]$Text) { Write-Host "  $YELLOW⚠ $Text$RESET" }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
function open_url([string]$Url) {
  Write-Host "  $GREEN↗ opening$RESET $Url"
  try {
    if ($IsWindows) { Start-Process $Url; return }
    foreach ($c in 'wslview', 'explorer.exe', 'xdg-open', 'open') {
      if (Get-Command $c -ErrorAction SilentlyContinue) { & $c $Url *> $null; return }
    }
  } catch {}
  warn "couldn't open a browser, so visit it manually: $Url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
function pause([string]$Message = 'Press Enter to continue') {
  Write-Host -NoNewline "  $DIM$Message$RESET "
  $null = [Console]::ReadLine()
}

# confirm "question" is a y/N gate; returns $true on yes.
function confirm([string]$Question) {
  Write-Host -NoNewline "  $YELLOW? $Question [y/N] "
  $reply = [Console]::ReadLine()
  return [bool]($reply -and $reply -match '^[Yy]')
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone. $null when absent.
function _existing([string]$Key) {
  $path = _env_path
  if (-not [IO.File]::Exists($path)) { return $null }
  $line = [IO.File]::ReadAllLines($path) | Where-Object { $_ -match "^$([regex]::Escape($Key))=" } | Select-Object -Last 1
  if (-not $line) { return $null }
  $value = $line.Substring($Key.Length + 1)
  if ($value.Length -ge 2 -and $value.StartsWith("'") -and $value.EndsWith("'")) {
    $value = $value.Substring(1, $value.Length - 2).Replace("'\''", "'")
  } elseif ($value.Length -ge 2 -and $value.StartsWith('"') -and $value.EndsWith('"')) {
    $value = $value.Substring(1, $value.Length - 2)
    if ($value -match '[\\$"]') { return $null }   # escapes, $ or ": can't decode safely; ask again
  }
  return $value
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret). Fails at
# EOF with no input.
function ask([string]$Key, [string]$Prompt) {
  $current = _existing $Key
  Write-Host -NoNewline "  $BOLD$Prompt$RESET "
  if ($current) { Write-Host -NoNewline "$DIM[Enter keeps current]$RESET " }
  $value = [Console]::ReadLine()
  if ($null -eq $value) { throw "no input for $Key" }
  if (-not $value -and $current) { $value = $current }
  Set-Variable -Name $Key -Value $value -Scope Script
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
function ask_secret([string]$Key, [string]$Prompt) {
  $current = _existing $Key
  Write-Host -NoNewline "  $BOLD$Prompt$RESET "
  if ($current) { Write-Host -NoNewline "$DIM[Enter keeps current]$RESET " }
  # Read-Host would wait on the console even when stdin is piped; read the pipe like bash does.
  $value = if ([Console]::IsInputRedirected) { [Console]::ReadLine() }
           else { [Net.NetworkCredential]::new('', (Read-Host -AsSecureString)).Password }
  if ($null -eq $value) { throw "no input for $Key" }
  if (-not $value -and $current) { $value = $current }
  Set-Variable -Name $Key -Value $value -Scope Script
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode. Writes LF line endings.
function write_env([string]$Key, [string]$Value) {
  $path = _env_path
  if (-not [IO.File]::Exists($path)) {
    [IO.File]::WriteAllText($path, '')
    if (-not $IsWindows) { chmod 600 $path }
  }
  $lines = @([IO.File]::ReadAllLines($path) | Where-Object { $_ -notmatch "^$([regex]::Escape($Key))=" })
  $lines += "$Key='$($Value.Replace("'", "'\''"))'"
  [IO.File]::WriteAllText($path, ($lines -join "`n") + "`n")
  Set-Variable -Name $Key -Value $Value -Scope Script
  $WRITTEN_ENV.Add($Key)
  Write-Host "  $GREEN✓ wrote$RESET $Key → $ENV_FILE"
}

function _gh_ready {
  if (-not (Get-Command gh -ErrorAction SilentlyContinue)) { return $false }
  gh auth status *> $null
  return $LASTEXITCODE -eq 0
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
function set_secret([string]$Name, [string]$Value) {
  if (_gh_ready) {
    # Feed the value on stdin, byte-exact: a PowerShell pipe to a native command
    # appends a newline, and --body would expose the secret in the process list.
    $psi = [Diagnostics.ProcessStartInfo]::new('gh')
    'secret', 'set', $Name | ForEach-Object { $psi.ArgumentList.Add($_) }
    $psi.WorkingDirectory = (Get-Location).ProviderPath
    $psi.RedirectStandardInput = $true
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $p = [Diagnostics.Process]::Start($psi)
    $p.StandardInput.Write($Value); $p.StandardInput.Close()
    $null = $p.StandardOutput.ReadToEndAsync(); $null = $p.StandardError.ReadToEnd()
    $p.WaitForExit()
    if ($p.ExitCode -eq 0) {
      $WRITTEN_SECRET.Add($Name)
      Write-Host "  $GREEN✓ set$RESET GitHub secret $Name"
      return
    }
  }
  $SKIPPED.Add("GitHub secret $Name (set it manually: gh secret set $Name)")
  warn "skipped GitHub secret ${Name}: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
function set_var([string]$Name, [string]$Value) {
  if (_gh_ready) {
    gh variable set $Name --body $Value *> $null
    if ($LASTEXITCODE -eq 0) {
      Write-Host "  $GREEN✓ set$RESET GitHub variable $Name"
      return
    }
  }
  $SKIPPED.Add("GitHub variable $Name")
  warn "skipped GitHub variable $Name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
function finish {
  _clear
  Write-Host "`n$BOLD$GREEN  ✓ Setup complete$RESET"
  if ($WRITTEN_ENV.Count) { note "wrote $($WRITTEN_ENV.Count) value(s) to ${ENV_FILE}: $($WRITTEN_ENV -join ' ')" }
  if ($WRITTEN_SECRET.Count) { note "set $($WRITTEN_SECRET.Count) GitHub secret(s): $($WRITTEN_SECRET -join ' ')" }
  if ($SKIPPED.Count) {
    Write-Host ''; warn 'still to do by hand:'
    foreach ($s in $SKIPPED) { note "  - $s" }
  }
  Write-Host ''
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage per step the human takes.
# Replace the example below. Set $script:TOTAL_STAGES to match the stages you
# write (a bare $TOTAL_STAGES = ... inside the function would only set a local).
# Read captured values as $KEY: ask and write_env set them at script scope.
# Gate irreversible actions with: if (confirm "...") { ... }
# ──────────────────────────────────────────────────────────────────────────

function run_wizard {

$script:TOTAL_STAGES = 1

banner 'Stripe setup'

# ── Example stage: replace with your real steps ───────────────────────────
stage 'Stripe: API keys'
say "We'll grab your Stripe test keys and store them for local dev + CI."
open_url 'https://dashboard.stripe.com/test/apikeys'
step 'On the API keys page, copy the Publishable key (starts pk_test_).'
ask STRIPE_PUBLISHABLE_KEY 'Paste the publishable key:'
step "Click 'Reveal test key' on the Secret key row, then copy it."
ask_secret STRIPE_SECRET_KEY 'Paste the secret key:'
write_env STRIPE_PUBLISHABLE_KEY $STRIPE_PUBLISHABLE_KEY
write_env STRIPE_SECRET_KEY $STRIPE_SECRET_KEY
set_secret STRIPE_SECRET_KEY $STRIPE_SECRET_KEY   # CI needs this one
# ──────────────────────────────────────────────────────────────────────────

finish
}

# The glyphs need a UTF-8 console; Windows defaults to an OEM code page.
$_ENCODING = [Console]::OutputEncoding
try { [Console]::OutputEncoding = [Text.Encoding]::UTF8; run_wizard @args }
finally { [Console]::OutputEncoding = $_ENCODING }
